self.addEventListener('push',event=>{let data={};try{data=event.data.json()}catch{}event.waitUntil(self.registration.showNotification(data.title||'Airdrop Museum',{body:data.body||'Ada pembaruan riset.',data:{url:'/?v=1.1.0#hub'},tag:'museum-update'}))});self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil(clients.openWindow('/?v=1.1.0#hub'))});
